Proof.
  intros p j q0 E.
  exists (4 * j + 8), (cden (Jp q0 ++ [S0;S1;S0]) [] j A1_1RB0LD_0LC1RA_1LA1RC_0RA1LD).
  split; [lia|]. split; [| exact (gei_1RB0LD_0LC1RA_1LA1RC_0RA1LD p j q0 E)].
  rewrite (gsi_1RB0LD_0LC1RA_1LA1RC_0RA1LD p j q0 E).
