  - destruct (lapi_1RB0LD_0LC1RA_1LA1RC_0RB1LD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LD_0LC1RA_1LA1RC_0RB1LD B0_1RB0LD_0LC1RA_1LA1RC_0RB1LD B1_1RB0LD_0LC1RA_1LA1RC_0RB1LD 4 12 p j' [] []).
    + exact run_ovf_1RB0LD_0LC1RA_1LA1RC_0RB1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_0LC1RA_1LA1RC_0RB1LD p j' E).
    + exact (geo_1RB0LD_0LC1RA_1LA1RC_0RB1LD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LD_0LC1RA_1LA1RC_0RB1LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 2)).
Proof.
