Lemma fireo_1RB0LD_0LC1RA_1RD1LC_0RA1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LD_0LC1RA_1RD1LC_0RA1LD = Some t ->
  forall p j, cview p = (S j, None) ->
