Lemma gsi_1RB0LD_0LC1RC_1RB0LD_1LA0RC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_1RB0LD_0LC1RC_1RB0LD_1LA0RC.
