Lemma gei_1RB0LD_0LC1RC_1RB0LD_1LA0RC : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Jp q0 ++ [S0]) [] j A1_1RB0LD_0LC1RC_1RB0LD_1LA0RC) = lift (Cc (Pos.succ p)).
