    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LD_0LC1RC_1RB0LD_1LA0RC B0_1RB0LD_0LC1RC_1RB0LD_1LA0RC B1_1RB0LD_0LC1RC_1RB0LD_1LA0RC 4 14 p j' [] []).
    + exact run_ovf_1RB0LD_0LC1RC_1RB0LD_1LA0RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_0LC1RC_1RB0LD_1LA0RC p j' E).
    + exact (geo_1RB0LD_0LC1RC_1RB0LD_1LA0RC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LD_0LC1RC_1RB0LD_1LA0RC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
