Lemma fireo_1RB0LD_0LC1RC_1RB0LD_1LA0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LD_0LC1RC_1RB0LD_1LA0RC = Some t ->
