Lemma lapi_1RB0LD_0RC1LA_1LA0RB_0LD1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0LD_0RC1LA_1LA0RB_0LD1RB p q0 E) as (HA & HB).
    exists (0 * 0 + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0LD_0RC1LA_1LA0RB_0LD1RB Z0_1RB0LD_0RC1LA_1LA0RB_0LD1RB Z1_1RB0LD_0RC1LA_1LA0RB_0LD1RB 0 6
               run_z_1RB0LD_0RC1LA_1LA0RB_0LD1RB (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0LD_0RC1LA_1LA0RB_0LD1RB p j' q0 E) as (HA & HB).
    exists (4 * j' + 10). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0LD_0RC1LA_1LA0RB_0LD1RB P0_1RB0LD_0RC1LA_1LA0RB_0LD1RB P1_1RB0LD_0RC1LA_1LA0RB_0LD1RB 4 10
               run_p_1RB0LD_0RC1LA_1LA0RB_0LD1RB (Ap_Alph_00_10_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB0LD_0RC1LA_1LA0RB_0LD1RB : forall p j, cview p = (S j, None) ->
