Lemma geo_1RB0LD_0RC1LA_1LA0RB_0LD1RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LD_0RC1LA_1LA0RB_0LD1RB) = lift (Cc (Pos.succ p)).
