      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0LD_0RC1LA_1LD1RC_0RC1LB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtrm_1RB0LD_0RC1LA_1LD1RC_0RC1LB : NeverQuasiHaltsTr tmm_1RB0LD_0RC1LA_1LD1RC_0RC1LB.
Proof.
