Lemma gei_1RB0LD_0RC1LB_1LD1RC_0RB1LA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_1RB0LD_0RC1LB_1LD1RC_0RB1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (_ & H2).
  unfold Cc_1RB0LD_0RC1LB_1LD1RC_0RB1LA, cden, A1_1RB0LD_0RC1LB_1LD1RC_0RB1LA; cbn [c_st c_l c_h c_r].
