(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LD_0RC1LB_1LD1RC_0RC1LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB0LD_0RC1LB_1LD1RC_0RC1LA.
