Lemma fire_1RB0LD_0RC1LB_1LD1RC_0RC1LA : forall t, ~ In t pins_1RB0LD_0RC1LB_1LD1RC_0RC1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
