  split; [lia|]. split; [| exact (gen_1RB0LD_0RC1LC_1LD1RC_0RB1LA v i q0 E)].
  rewrite (gsn_1RB0LD_0RC1LC_1LD1RC_0RB1LA v i q0 E).
  exact (srun_sound tm false true chn_1RB0LD_0RC1LC_1LD1RC_0RB1LA AI0_1RB0LD_0RC1LC_1LD1RC_0RB1LA AI1_1RB0LD_0RC1LC_1LD1RC_0RB1LA 4 16
           run_inner_1RB0LD_0RC1LC_1LD1RC_0RB1LA (Ip q0 ++ [S1]) [] i
