(** ** The lap *)

Lemma lap_1RB0LD_0RC1LD_1LD0RA_1LB1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
