(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LD_0RC1LD_1LD0RA_1LB1RC : forall t, ~ In t pins_1RB0LD_0RC1LD_1LD0RA_1LB1RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0LD_0RC1LD_1LD0RA_1LB1RC.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_0RC1LD_1LD0RA_1LB1RC (StA, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_0RC1LD_1LD0RA_1LB1RC [SRotL 1; SWin 1; SCycL 4 0; SWin 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0LD_0RC1LD_1LD0RA_1LB1RC
      with (l := [SRotL 1; SWin 1; SCycL 4 0; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0LD_0RC1LD_1LD0RA_1LB1RC
      with (l := []).
    vm_compute; reflexivity.
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_0RC1LD_1LD0RA_1LB1RC (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_0RC1LD_1LD0RA_1LB1RC [SRotL 1; SWin 1; SCycL 4 0; SWin 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_0RC1LD_1LD0RA_1LB1RC (StC, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_0RC1LD_1LD0RA_1LB1RC [SRotL 1; SWin 1; SCycL 4 0; SWin 4; SWinL 3] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LD_0RC1LD_1LD0RA_1LB1RC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0LD_0RC1LD_1LD0RA_1LB1RC
      with (l := [SRotL 1; SWin 1; SCycL 4 0; SWin 2]).
    vm_compute; reflexivity.
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_0RC1LD_1LD0RA_1LB1RC (StD, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_0RC1LD_1LD0RA_1LB1RC [SRotL 1; SWin 1; SCycL 4 0; SWin 3] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

