      exact (srun_sound tm true true chb_1RB0LD_0RC1RA_0LC1LA_0RA1LD B0_1RB0LD_0RC1RA_0LC1LA_0RA1LD BB1_1RB0LD_0RC1RA_0LC1LA_0RA1LD 4 16
               run_boot_1RB0LD_0RC1RA_0LC1LA_0RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB0LD_0RC1RA_0LC1LA_0RA1LD p (pow2 j) (pow2 j));
        [exact HB1|].
