      exact (srun_sound tm true true chm_1RB0LD_0RC1RA_0LC1LA_0RA1LD BM0_1RB0LD_0RC1RA_0LC1LA_0RA1LD BM1_1RB0LD_0RC1RA_0LC1LA_0RA1LD 4 8
               run_shift_1RB0LD_0RC1RA_0LC1LA_0RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    exact HB2.
