Lemma gsi_1RB0LD_0RC1RA_0LC1LA_0RB1LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0;S1;S0]) [] j A0_1RB0LD_0RC1RA_0LC1LA_0RB1LD.
