Lemma geo_1RB0LD_0RC1RA_0LC1LD_1LA0RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LD_0RC1RA_0LC1LD_1LA0RA) = lift (Cc (Pos.succ p)).
