(** ** The lap *)

Lemma lap_1RB0LD_0RC1RA_1LC0LD_0RA1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
