(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LD_0RC1RA_1LC0RB_1LB1LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0;S1;S0]) [] j A0_1RB0LD_0RC1RA_1LC0RB_1LB1LD.
