  - destruct (lapi_1RB0LD_0RC1RA_1LC0RB_1LB1LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LD_0RC1RA_1LC0RB_1LB1LD B0_1RB0LD_0RC1RA_1LC0RB_1LB1LD B1_1RB0LD_0RC1RA_1LC0RB_1LB1LD 4 20 p j' [] []).
    + exact run_ovf_1RB0LD_0RC1RA_1LC0RB_1LB1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_0RC1RA_1LC0RB_1LB1LD p j' E).
    + exact (geo_1RB0LD_0RC1RA_1LC0RB_1LB1LD p j' E).
    + lia.
