Definition tm_1RB0LD_0RC1RA_1LC1LD_0RA1LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StD
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S1 DL StC | StC, S1 => mk S1 DL StD
