  { unfold Cin_1RB0LD_0RC1RA_1LC1LD_0RA1LD. rewrite epow2_1RB0LD_0RC1RA_1LC1LD_0RA1LD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
