  destruct (JpCounter.cview_none_J (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB0LD_0RC1RA_1LC1LD_0RA1LD, cden, BE0_1RB0LD_0RC1RA_1LC1LD_0RA1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB0LD_0RC1RA_1LC1LD_0RA1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB0LD_0RC1RA_1LC1LD_0RA1LD. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LD_0RC1RA_1LC1LD_0RA1LD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LD_0RC1RA_1LC1LD_0RA1LD p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB0LD_0RC1RA_1LC1LD_0RA1LD).
    split; [lia|]. split; [| exact (gbo_1RB0LD_0RC1RA_1LC1LD_0RA1LD j)].
    rewrite (gso_1RB0LD_0RC1RA_1LC1LD_0RA1LD p j E).
    exact (srun_sound tm true true chb_1RB0LD_0RC1RA_1LC1LD_0RA1LD B0_1RB0LD_0RC1RA_1LC1LD_0RA1LD BB1_1RB0LD_0RC1RA_1LC1LD_0RA1LD 4 8
             run_boot_1RB0LD_0RC1RA_1LC1LD_0RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 12), (cden [] [] j B1_1RB0LD_0RC1RA_1LC1LD_0RA1LD).
    split; [| exact (geo_1RB0LD_0RC1RA_1LC1LD_0RA1LD p j E)].
    rewrite (gxi_1RB0LD_0RC1RA_1LC1LD_0RA1LD j).
    exact (srun_sound tm true true che_1RB0LD_0RC1RA_1LC1LD_0RA1LD BE0_1RB0LD_0RC1RA_1LC1LD_0RA1LD B1_1RB0LD_0RC1RA_1LC1LD_0RA1LD 4 12
             run_exit_1RB0LD_0RC1RA_1LC1LD_0RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_1RB0LD_0RC1RA_1LC1LD_0RA1LD : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_1RB0LD_0RC1RA_1LC1LD_0RA1LD = Some q ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ fst e = q.
Proof.
  intros l q Hst p j E.
  apply (vis_via_fill tm Cc Cin lapin_1RB0LD_0RC1RA_1LC1LD_0RA1LD q p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB0LD_0RC1RA_1LC1LD_0RA1LD). split;
      [| exact (gbo_1RB0LD_0RC1RA_1LC1LD_0RA1LD j)].
    rewrite (gso_1RB0LD_0RC1RA_1LC1LD_0RA1LD p j E).
    exact (srun_sound tm true true chb_1RB0LD_0RC1RA_1LC1LD_0RA1LD B0_1RB0LD_0RC1RA_1LC1LD_0RA1LD BB1_1RB0LD_0RC1RA_1LC1LD_0RA1LD 4 8
             run_boot_1RB0LD_0RC1RA_1LC1LD_0RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (vis_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (vis_of_run tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB0LD_0RC1RA_1LC1LD_0RA1LD xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB0LD_0RC1RA_1LC1LD_0RA1LD j)].
Qed.



(** ** The lap *)

Lemma lap_1RB0LD_0RC1RA_1LC1LD_0RA1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LD_0RC1RA_1LC1LD_0RA1LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LD_0RC1RA_1LC1LD_0RA1LD p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LD_0RC1RA_1LC1LD_0RA1LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 8.
  assert (H : match csteps tm 8 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 8 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LD_0RC1RA_1LC1LD_0RA1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LD_0RC1RA_1LC1LD_0RA1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LD_0RC1RA_1LC1LD_0RA1LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LD_0RC1RA_1LC1LD_0RA1LD p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB0LD_0RC1RA_1LC1LD_0RA1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0LD_0RC1RA_1LC1LD_0RA1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB0LD_0RC1RA_1LC1LD_0RA1LD t p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB0LD_0RC1RA_1LC1LD_0RA1LD). split;
      [| exact (gbo_1RB0LD_0RC1RA_1LC1LD_0RA1LD j)].
    rewrite (gso_1RB0LD_0RC1RA_1LC1LD_0RA1LD p j E).
    exact (srun_sound tm true true chb_1RB0LD_0RC1RA_1LC1LD_0RA1LD B0_1RB0LD_0RC1RA_1LC1LD_0RA1LD BB1_1RB0LD_0RC1RA_1LC1LD_0RA1LD 4 8
             run_boot_1RB0LD_0RC1RA_1LC1LD_0RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB0LD_0RC1RA_1LC1LD_0RA1LD xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB0LD_0RC1RA_1LC1LD_0RA1LD j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LD_0RC1RA_1LC1LD_0RA1LD : forall t, ~ In t pins_1RB0LD_0RC1RA_1LC1LD_0RA1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0LD_0RC1RA_1LC1LD_0RA1LD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_0RC1RA_1LC1LD_0RA1LD [] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_0RC1RA_1LC1LD_0RA1LD [SCycL 2 0; SWin 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_0RC1RA_1LC1LD_0RA1LD (StB, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_0RC1RA_1LC1LD_0RA1LD [SCycL 2 0; SWin 1; SWinL 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_0RC1RA_1LC1LD_0RA1LD [SCycL 2 0; SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_0RC1RA_1LC1LD_0RA1LD (StC, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_0RC1RA_1LC1LD_0RA1LD [SCycL 2 0; SWin 1; SWinL 3] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_0RC1RA_1LC1LD_0RA1LD (StC, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_0RC1RA_1LC1LD_0RA1LD [SCycL 2 0; SWin 1; SWinL 5] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_0RC1RA_1LC1LD_0RA1LD [SCycL 2 0; SWin 4; SCycR 2; SWinR 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_0RC1RA_1LC1LD_0RA1LD [SCycL 2 0; SWin 3] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtrm_1RB0LD_0RC1RA_1LC1LD_0RA1LD : NeverQuasiHaltsTr tmm_1RB0LD_0RC1RA_1LC1LD_0RA1LD.
Proof.
  apply (glue_neverqhtr tmm_1RB0LD_0RC1RA_1LC1LD_0RA1LD pins_1RB0LD_0RC1RA_1LC1LD_0RA1LD Cc 1).
  - exact boot_1RB0LD_0RC1RA_1LC1LD_0RA1LD.
  - intros p _. apply lap_1RB0LD_0RC1RA_1LC1LD_0RA1LD.
  - intros t Ht p _. apply fire_1RB0LD_0RC1RA_1LC1LD_0RA1LD. exact Ht.
Qed.

Theorem nqhtr_1RB0LD_0RC1RA_1LC1LD_0RA1LD : NeverQuasiHaltsTr tm_1RB0LD_0RC1RA_1LC1LD_0RA1LD.
Proof. apply (neverqhtr_mirror tm_1RB0LD_0RC1RA_1LC1LD_0RA1LD). rewrite mirror_ok_1RB0LD_0RC1RA_1LC1LD_0RA1LD. exact nqhtrm_1RB0LD_0RC1RA_1LC1LD_0RA1LD. Qed.

Theorem nonhalt_1RB0LD_0RC1RA_1LC1LD_0RA1LD : NonHalt tm_1RB0LD_0RC1RA_1LC1LD_0RA1LD.
Proof. apply never_qh_tr_nonhalt, nqhtr_1RB0LD_0RC1RA_1LC1LD_0RA1LD. Qed.

End LAPT_1RB0LD_0RC1RA_1LC1LD_0RA1LD.

Module LAPT_1RB0LD_0RC1RA_1LC1LD_0RB1LD.
(** * LAPT_1RB0LD_0RC1RA_1LC1LD_0RB1LD: TRANSITION-LEVEL board for machine 1RB0LD_0RC1RA_1LC1LD_0RB1LD, boarded by CERTIFICATE.

    Auto-emitted by tools/counters/emit_lapcert.py (UNTRUSTED emitter; the Coq
    kernel re-runs the checker on every line below).  Left-growth binary
    counter under the Jp digit alphabet (JpCounter.v), anchored at

      Cc p = (StD, (Jp p ++ [S1;S0], S0, []))

    The lap is DATA, not a proof script: each branch is a list of steps for
    [Checkers/LapDecider.v], run by the kernel through [vm_compute] and
    discharged by the single theorem [srun_sound].

      interior  (cview p = (j, Some q0)):  4*j+4 steps
      overflow  (cview p = (S j, None)):   boot 4*j+4, then the inner counter's own laps to the
                                           all-ones fill, then exit 4*j+8

    The interior branch closes EXACTLY (which is what feeds
    [LapCertGlue.reach_ovf]); the overflow branch closes one blank short of
    the anchor tail, hence up to [lift].

    Differentially validated against the raw simulator on BOTH branches --
    step counts AND exact configurations -- for 192 interior anchors (interior); 6 overflow phases, j = 2..7 (246 inner laps) (nested overflow).
    Axiom footprint: [functional_extensionality_dep] (via [CTape.lift]). *)
Import Arith Lia Bool List PArith Wellfounded.
Import BBB4_Statement CTape Mirror.
Import FunctionalExtensionality.
Import WTape LapGlue LapGlueQH LapGlueAbs
                                  MonoCounter JpCounter JpCounter LapCertGlue LapCertGlueLift IXPGadgets NestedLap NestedLapLift.
