Lemma gsi_1RB0LD_0RC1RC_1LA0RC_0RA0LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Bp q0 ++ [S0]) [] j A0_1RB0LD_0RC1RC_1LA0RC_0RA0LD.
