Lemma gei_1RB0LD_0RC1RC_1LA0RC_0RA0LD : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Bp q0 ++ [S0]) [] j A1_1RB0LD_0RC1RC_1LA0RC_0RA0LD) = lift (Cc (Pos.succ p)).
