  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StD
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S1 DR StC
  | StC, S0 => mk S1 DL StA | StC, S1 => mk S1 DR StC
  | StD, S0 => mk S0 DR StA | StD, S1 => mk S0 DL StD end.

(** Its mirror 1LB0RD_0LC1LC_1RA1LC_0LA0RD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0LD_0RC1RC_1LA1RC_0RA0LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StD
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S1 DL StC
  | StC, S0 => mk S1 DR StA | StC, S1 => mk S1 DL StC
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S0 DR StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LD_0RC1RC_1LA1RC_0RA0LD : list Instr := [].
Definition tmw_1RB0LD_0RC1RC_1LA1RC_0RA0LD : TM := tm_wrap_trs tmm_1RB0LD_0RC1RC_1LA1RC_0RA0LD pins_1RB0LD_0RC1RC_1LA1RC_0RA0LD.
Local Notation tm := tmw_1RB0LD_0RC1RC_1LA1RC_0RA0LD.

Lemma mirror_ok_1RB0LD_0RC1RC_1LA1RC_0RA0LD : mirror_tm tm_1RB0LD_0RC1RC_1LA1RC_0RA0LD = tmm_1RB0LD_0RC1RC_1LA1RC_0RA0LD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB0LD_0RC1RC_1LA1RC_0RA0LD (p : positive) : cconf := (StC, (Kp p ++ [S0], S0, [S0;S1])).
