(** ** The lap *)

Lemma lap_1RB0LD_1LC0RA_0RB1RD_1LC1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
