    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LD_1LC0RA_0RB1RD_1LC1LD B0_1RB0LD_1LC0RA_0RB1RD_1LC1LD B1_1RB0LD_1LC0RA_0RB1RD_1LC1LD 6 8 p j' [] []).
    + exact run_ovf_1RB0LD_1LC0RA_0RB1RD_1LC1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_1LC0RA_0RB1RD_1LC1LD p j' E).
    + exact (geo_1RB0LD_1LC0RA_0RB1RD_1LC1LD p j' E).
    + lia.
