    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LD_1LC0RA_0RD1LB_1LC1RA B0_1RB0LD_1LC0RA_0RD1LB_1LC1RA B1_1RB0LD_1LC0RA_0RD1LB_1LC1RA 4 12 p j' [] []).
    + exact run_ovf_1RB0LD_1LC0RA_0RD1LB_1LC1RA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_1LC0RA_0RD1LB_1LC1RA p j' E).
    + exact (geo_1RB0LD_1LC0RA_0RD1LB_1LC1RA p j' E).
    + lia.
