(** ** The lap *)

Lemma lap_1RB0LD_1LC0RB_0LC1LD_0RA___ : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
