  - destruct (lapi_1RB0LD_1LC0RB_0LC1LD_0RA___ p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LD_1LC0RB_0LC1LD_0RA___ B0_1RB0LD_1LC0RB_0LC1LD_0RA___ B1_1RB0LD_1LC0RB_0LC1LD_0RA___ 2 8 p j' [] []).
    + exact run_ovf_1RB0LD_1LC0RB_0LC1LD_0RA___.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_1LC0RB_0LC1LD_0RA___ p j' E).
    + exact (geo_1RB0LD_1LC0RB_0LC1LD_0RA___ p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LD_1LC0RB_0LC1LD_0RA___ : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 6.
  assert (H : match csteps tm 6 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 6 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

