  apply (fire_of_run_instr tm Cc true true l B0_1RB0LD_1LC0RB_0LC1LD_0RA___ p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LD_1LC0RB_0LC1LD_0RA___ p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LD_1LC0RB_0LC1LD_0RA___ : forall t, ~ In t pins_1RB0LD_1LC0RB_0LC1LD_0RA___ ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
