  - destruct (lapi_1RB0LD_1LC0RB_0LC1LD_1RA0RA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LD_1LC0RB_0LC1LD_1RA0RA B0_1RB0LD_1LC0RB_0LC1LD_1RA0RA B1_1RB0LD_1LC0RB_0LC1LD_1RA0RA 2 8 p j' [] []).
    + exact run_ovf_1RB0LD_1LC0RB_0LC1LD_1RA0RA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_1LC0RB_0LC1LD_1RA0RA p j' E).
    + exact (geo_1RB0LD_1LC0RB_0LC1LD_1RA0RA p j' E).
    + lia.
