(** ** The lap *)

Lemma lap_1RB0LD_1LC0RD_1RD1LC_0LC1RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LD_1LC0RD_1RD1LC_0LC1RA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LD_1LC0RD_1RD1LC_0LC1RA B0_1RB0LD_1LC0RD_1RD1LC_0LC1RA B1_1RB0LD_1LC0RD_1RD1LC_0LC1RA 8 32 p j' [] []).
    + exact run_ovf_1RB0LD_1LC0RD_1RD1LC_0LC1RA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_1LC0RD_1RD1LC_0LC1RA p j' E).
    + exact (geo_1RB0LD_1LC0RD_1RD1LC_0LC1RA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LD_1LC0RD_1RD1LC_0LC1RA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 23.
  assert (H : match csteps tm 23 c0 with
