Definition AI0_1RB0LD_1LC1RA_0LD1LC_0RA1LD : sconf := mkC StA (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition AI1_1RB0LD_1LC1RA_0LD1LC_0RA1LD : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S0] [] 0 0 []).
Definition chn_1RB0LD_1LC1RA_0LD1LC_0RA1LD : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWinR 4].

Lemma run_inner_1RB0LD_1LC1RA_0LD1LC_0RA1LD : srun tm false true chn_1RB0LD_1LC1RA_0LD1LC_0RA1LD AI0_1RB0LD_1LC1RA_0LD1LC_0RA1LD = Some (AI1_1RB0LD_1LC1RA_0LD1LC_0RA1LD, 4, 8).
