  exists (4 * j + 8), (cden (Jp q0 ++ [S0]) [] j A1_1RB0LD_1LC1RA_0LD1RC_0RA1LD).
  split; [lia|]. split; [| exact (gei_1RB0LD_1LC1RA_0LD1RC_0RA1LD p j q0 E)].
  rewrite (gsi_1RB0LD_1LC1RA_0LD1RC_0RA1LD p j q0 E).
