(** ** The lap *)

Lemma lap_1RB0LD_1LC1RA_0LD1RC_0RA1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
