    apply (lap_of_run tm Cc true true cho_1RB0LD_1LC1RA_0LD1RC_0RA1LD B0_1RB0LD_1LC1RA_0LD1RC_0RA1LD B1_1RB0LD_1LC1RA_0LD1RC_0RA1LD 4 14 p j' [] []).
    + exact run_ovf_1RB0LD_1LC1RA_0LD1RC_0RA1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_1LC1RA_0LD1RC_0RA1LD p j' E).
    + exact (geo_1RB0LD_1LC1RA_0LD1RC_0RA1LD p j' E).
