    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0LD_1LC1RA_0RB1LC_0RC1LD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0LD_1LC1RA_0RB1LC_0RC1LD
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LD_1LC1RA_0RB1LC_0RC1LD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 2]).
