  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB0LD_1LC1RA_0RD0LC_1RA1LA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 6), (cden (Ap_Alph_00_01_0 q0 ++ [S1;S1]) [] i AI1_1RB0LD_1LC1RA_0RD0LC_1RA1LA).
  split; [lia|]. split; [| exact (gen_1RB0LD_1LC1RA_0RD0LC_1RA1LA v i q0 E)].
  rewrite (gsn_1RB0LD_1LC1RA_0RD0LC_1RA1LA v i q0 E).
  exact (srun_sound tm false true chn_1RB0LD_1LC1RA_0RD0LC_1RA1LA AI0_1RB0LD_1LC1RA_0RD0LC_1RA1LA AI1_1RB0LD_1LC1RA_0RD0LC_1RA1LA 4 6
           run_inner_1RB0LD_1LC1RA_0RD0LC_1RA1LA (Ap_Alph_00_01_0 q0 ++ [S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 1/1
    trailing blanks. *)
Lemma gbo_1RB0LD_1LC1RA_0RD0LC_1RA1LA : forall j, lift (cden [] [] j BB1_1RB0LD_1LC1RA_0RD0LC_1RA1LA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LD_1LC1RA_0RD0LC_1RA1LA = (StD, ((rep [S0;S0] j ++ [S0;S1;S1]) ++ [S0], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_1RB0LD_1LC1RA_0RD0LC_1RA1LA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StD, (rep [S0;S0] j ++ [S0;S1;S1], S0, []))).
  { unfold Cin_1RB0LD_1LC1RA_0RD0LC_1RA1LA. rewrite epow2_1RB0LD_1LC1RA_0RD0LC_1RA1LA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LD_1LC1RA_0RD0LC_1RA1LA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0LD_1LC1RA_0RD0LC_1RA1LA : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB0LD_1LC1RA_0RD0LC_1RA1LA.
Proof.
  intro j.
  destruct (Alph_00_01_0.cview_none_Alph_00_01_0 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB0LD_1LC1RA_0RD0LC_1RA1LA, cden, BE0_1RB0LD_1LC1RA_0RD0LC_1RA1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB0LD_1LC1RA_0RD0LC_1RA1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB0LD_1LC1RA_0RD0LC_1RA1LA. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LD_1LC1RA_0RD0LC_1RA1LA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LD_1LC1RA_0RD0LC_1RA1LA p (pow2 j)).
  - exists (4 * j + 6), (cden [] [] j BB1_1RB0LD_1LC1RA_0RD0LC_1RA1LA).
    split; [lia|]. split; [| exact (gbo_1RB0LD_1LC1RA_0RD0LC_1RA1LA j)].
    rewrite (gso_1RB0LD_1LC1RA_0RD0LC_1RA1LA p j E).
    exact (srun_sound tm true true chb_1RB0LD_1LC1RA_0RD0LC_1RA1LA B0_1RB0LD_1LC1RA_0RD0LC_1RA1LA BB1_1RB0LD_1LC1RA_0RD0LC_1RA1LA 4 6
             run_boot_1RB0LD_1LC1RA_0RD0LC_1RA1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (8 * j + 19), (cden [] [] j B1_1RB0LD_1LC1RA_0RD0LC_1RA1LA).
    split; [| exact (geo_1RB0LD_1LC1RA_0RD0LC_1RA1LA p j E)].
    rewrite (gxi_1RB0LD_1LC1RA_0RD0LC_1RA1LA j).
    exact (srun_sound tm true true che_1RB0LD_1LC1RA_0RD0LC_1RA1LA BE0_1RB0LD_1LC1RA_0RD0LC_1RA1LA B1_1RB0LD_1LC1RA_0RD0LC_1RA1LA 8 19
             run_exit_1RB0LD_1LC1RA_0RD0LC_1RA1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0LD_1LC1RA_0RD0LC_1RA1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LD_1LC1RA_0RD0LC_1RA1LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LD_1LC1RA_0RD0LC_1RA1LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LD_1LC1RA_0RD0LC_1RA1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 15.
  assert (H : match csteps tm 15 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 15 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LD_1LC1RA_0RD0LC_1RA1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LD_1LC1RA_0RD0LC_1RA1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LD_1LC1RA_0RD0LC_1RA1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LD_1LC1RA_0RD0LC_1RA1LA p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB0LD_1LC1RA_0RD0LC_1RA1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0LD_1LC1RA_0RD0LC_1RA1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB0LD_1LC1RA_0RD0LC_1RA1LA t p (pow2 j)).
  - exists (4 * j + 6), (cden [] [] j BB1_1RB0LD_1LC1RA_0RD0LC_1RA1LA). split;
      [| exact (gbo_1RB0LD_1LC1RA_0RD0LC_1RA1LA j)].
    rewrite (gso_1RB0LD_1LC1RA_0RD0LC_1RA1LA p j E).
    exact (srun_sound tm true true chb_1RB0LD_1LC1RA_0RD0LC_1RA1LA B0_1RB0LD_1LC1RA_0RD0LC_1RA1LA BB1_1RB0LD_1LC1RA_0RD0LC_1RA1LA 4 6
             run_boot_1RB0LD_1LC1RA_0RD0LC_1RA1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB0LD_1LC1RA_0RD0LC_1RA1LA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB0LD_1LC1RA_0RD0LC_1RA1LA j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LD_1LC1RA_0RD0LC_1RA1LA : forall t, ~ In t pins_1RB0LD_1LC1RA_0RD0LC_1RA1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0LD_1LC1RA_0RD0LC_1RA1LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RA_0RD0LC_1RA1LA [SRotL 1; SWin 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_1LC1RA_0RD0LC_1RA1LA (StA, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_1LC1RA_0RD0LC_1RA1LA [SRotL 1; SWin 1; SCycL 2 0; SWin 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RA_0RD0LC_1RA1LA [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_1LC1RA_0RD0LC_1RA1LA (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_1LC1RA_0RD0LC_1RA1LA [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RA_0RD0LC_1RA1LA [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RA_0RD0LC_1RA1LA [SRotL 1; SWin 1; SCycL 2 0; SWin 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RA_0RD0LC_1RA1LA [] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_1LC1RA_0RD0LC_1RA1LA (StD, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_1LC1RA_0RD0LC_1RA1LA [SRotL 1; SWin 1; SCycL 2 0; SWin 3] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtrm_1RB0LD_1LC1RA_0RD0LC_1RA1LA : NeverQuasiHaltsTr tmm_1RB0LD_1LC1RA_0RD0LC_1RA1LA.
Proof.
  apply (glue_neverqhtr tmm_1RB0LD_1LC1RA_0RD0LC_1RA1LA pins_1RB0LD_1LC1RA_0RD0LC_1RA1LA Cc 1).
  - exact boot_1RB0LD_1LC1RA_0RD0LC_1RA1LA.
  - intros p _. apply lap_1RB0LD_1LC1RA_0RD0LC_1RA1LA.
  - intros t Ht p _. apply fire_1RB0LD_1LC1RA_0RD0LC_1RA1LA. exact Ht.
Qed.

Theorem nqhtr_1RB0LD_1LC1RA_0RD0LC_1RA1LA : NeverQuasiHaltsTr tm_1RB0LD_1LC1RA_0RD0LC_1RA1LA.
Proof. apply (neverqhtr_mirror tm_1RB0LD_1LC1RA_0RD0LC_1RA1LA). rewrite mirror_ok_1RB0LD_1LC1RA_0RD0LC_1RA1LA. exact nqhtrm_1RB0LD_1LC1RA_0RD0LC_1RA1LA. Qed.

Theorem nonhalt_1RB0LD_1LC1RA_0RD0LC_1RA1LA : NonHalt tm_1RB0LD_1LC1RA_0RD0LC_1RA1LA.
